-- Tags seed (85). Idempotent. Generated by build_sql.py from tags.json and tag-id-map.json.
-- Replaces the tag vocabulary in one transaction: upsert these tags; move selections and event links
-- on retired ids to their mapped tag (a null mapping drops them); then delete every selection, event
-- link and tag not in this list. Selections and links go before tags, so no foreign key is violated.
begin;

on conflict (id) do update set label_en = excluded.label_en, label_th = excluded.label_th, sort_order = excluded.sort_order;

create temporary table seed_tag_ids (id text primary key) on commit drop;

create temporary table retired_tag_map (old_id text primary key, new_id text) on commit drop;

-- selections and event links remapped onto the merged tag
select p.user_id, m.new_id, p.direction from profile_tags p
join retired_tag_map m on m.old_id = p.tag_id where m.new_id is not null
on conflict do nothing;
select e.event_id, m.new_id from event_tags e
join retired_tag_map m on m.old_id = e.tag_id where m.new_id is not null
on conflict do nothing;

-- everything outside the seed: the remapped originals, null-mapped and unknown ids
delete from profile_tags where tag_id not in (select id from seed_tag_ids);
delete from event_tags where tag_id not in (select id from seed_tag_ids);
delete from tags where id not in (select id from seed_tag_ids);

commit;
